import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

min_reduce_cpp_decl = r"""
#include <torch/extension.h>
torch::Tensor min_reduce_dim(torch::Tensor x, int64_t dim);
"""

min_reduce_cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>

#include <cute/tensor.hpp>

using namespace cute;

// Reduction over the "middle" mode of a logically 3-D contiguous tensor:
//   X has logical shape (outer, R, inner), strides (R*inner, inner, 1)
//   Y has logical shape (outer, inner),      strides (inner, 1)
//   Y(o, w) = min_r X(o, r, w)
//
// Optimization: 128-bit vectorized global loads. Each thread owns one
// contiguous 4-wide slot of the inner mode and reduces it over all R.
// Row starts are not 16-byte aligned in general (inner may be odd), so
// each row uses one aligned float4 load plus a second overlapping one
// when the slot is misaligned; the shift t is uniform across the whole
// block, so the lane-select branches are warp-uniform. Row 0 and the
// very last row of the tensor are done with scalar loads so the
// overlapping load never touches memory outside the allocation.
template <typename T>
__device__ __forceinline__ void min4_row(const T* __restrict__ addr, float (&acc)[4])
{
  const unsigned t = (unsigned)(((uintptr_t)addr >> 2) & 3u);
  const float4 a = *reinterpret_cast<const float4*>(addr - t);
  float v0, v1, v2, v3;
  if (t == 0u) {
    v0 = a.x; v1 = a.y; v2 = a.z; v3 = a.w;
  } else {
    const float4 b = *reinterpret_cast<const float4*>(addr - t + 4);
    if (t == 1u)      { v0 = a.y; v1 = a.z; v2 = a.w; v3 = b.x; }
    else if (t == 2u) { v0 = a.z; v1 = a.w; v2 = b.x; v3 = b.y; }
    else              { v0 = a.w; v1 = b.x; v2 = b.y; v3 = b.z; }
  }
  acc[0] = fminf(acc[0], v0);
  acc[1] = fminf(acc[1], v1);
  acc[2] = fminf(acc[2], v2);
  acc[3] = fminf(acc[3], v3);
}
template <typename T, int Threads>
__global__ void min_reduce_middle_kernel(const T* __restrict__ X,
                                         T* __restrict__ Y,
                                         int64_t outer,
                                         int64_t R,
                                         int64_t inner)
{
  const int64_t o = blockIdx.y;
  const int64_t w0 = ((int64_t)blockIdx.x * Threads + threadIdx.x) * 4;
  // CUTE views of the full tensors.
  Tensor mX = make_tensor(make_gmem_ptr(X),
                          make_shape(outer, R, inner),
                          make_stride(R * inner, inner, Int<1>{}));
  Tensor mY = make_tensor(make_gmem_ptr(Y),
                          make_shape(outer, inner),
                          make_stride(inner, Int<1>{}));
  if (w0 >= inner) return;
  const int n = (inner - w0 >= 4) ? 4 : (int)(inner - w0);
  float acc[4];
  #pragma unroll
  for (int k = 0; k < 4; ++k) acc[k] = __int_as_float(0x7f800000); // +inf
  if (n < 4) {
    // Tail slot at the end of the inner mode: plain scalar reduction.
    for (int64_t r = 0; r < R; ++r) {
      #pragma unroll
      for (int k = 0; k < 4; ++k) {
        if (k < n) acc[k] = fminf(acc[k], (float)mX(o, r, w0 + k));
      }
    }
  } else if (R > 0) {
    // Row r = 0 with scalar loads (always fully in-bounds).
    #pragma unroll
    for (int k = 0; k < 4; ++k) acc[k] = (float)mX(o, 0, w0 + k);
    // Interior rows: vectorized path (the overlapping load stays inside
    // the allocation because a following row always exists).
    for (int64_t r = 1; r < R - 1; ++r) min4_row(&mX(o, r, w0), acc);
    if (R >= 2) {
      const int64_t r = R - 1;
      if (o != outer - 1) {
        min4_row(&mX(o, r, w0), acc);
      } else {
        // Very last row of the tensor: the overlapping 128-bit load
        // could overrun the allocation, so finish with scalar loads.
        #pragma unroll
        for (int k = 0; k < 4; ++k) acc[k] = fminf(acc[k], (float)mX(o, r, w0 + k));
      }
    }
  }
  #pragma unroll
  for (int k = 0; k < 4; ++k) {
    if (k < n) mY(o, w0 + k) = static_cast<T>(acc[k]);
  }
}

torch::Tensor min_reduce_dim(torch::Tensor x, int64_t dim) {
  TORCH_CHECK(x.is_cuda(), "x must be a CUDA tensor");
  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(x.dim() >= 1, "x must have at least one dimension");

  auto x_c = x.contiguous();
  const int64_t nd = x_c.dim();
  if (dim < 0) dim += nd;
  TORCH_CHECK(dim >= 0 && dim < nd, "dim out of range");

  int64_t outer = 1;
  for (int64_t i = 0; i < dim; ++i) outer *= x_c.size(i);
  const int64_t R = x_c.size(dim);
  int64_t inner = 1;
  for (int64_t i = dim + 1; i < nd; ++i) inner *= x_c.size(i);

  std::vector<int64_t> out_sizes;
  out_sizes.reserve(nd - 1);
  for (int64_t i = 0; i < nd; ++i) {
    if (i != dim) out_sizes.push_back(x_c.size(i));
  }
  auto y = torch::empty(out_sizes, x_c.options());

  if (y.numel() == 0) return y;

  constexpr int Threads = 256;
  const int64_t slots = (inner + 3) / 4;  // one thread per 4-wide inner slot
  dim3 block(Threads);
  dim3 grid((unsigned)((slots + Threads - 1) / Threads), (unsigned)outer, 1);
  TORCH_CHECK(outer <= 65535, "outer dimension too large for grid.y");
  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();
  min_reduce_middle_kernel<float, Threads>
      <<<grid, block, 0, stream>>>(x_c.data_ptr<float>(),
                                   y.data_ptr<float>(),
                                   outer, R, inner);

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess,
              "min_reduce_middle_kernel launch failed: ",
              cudaGetErrorString(err));

  return y;
}
"""

min_reduce_ext = load_inline(
    name="cute_min_reduce_ext",
    cpp_sources=min_reduce_cpp_decl,
    cuda_sources=min_reduce_cuda_src,
    functions=["min_reduce_dim"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=[
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include",
        "/home/tarasaba/PycharmProjects/cutegen_test/cutegen/cutlass/include/cute/",
    ],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Min reduction over a specific dimension, implemented with a single
    custom CUDA kernel written with CuTe tensors/layouts.
    """
    def __init__(self, dim: int):
        super(ModelNew, self).__init__()
        self.dim = int(dim)
        self._ext = min_reduce_ext

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self._ext.min_reduce_dim(x.contiguous(), self.dim)

